     1→import { useQuery, useQueryClient } from "@tanstack/react-query";
     2→import { supabase } from "@/integrations/supabase/client";
     3→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
     4→import { Button } from "@/components/ui/button";
     5→import { Badge } from "@/components/ui/badge";
     6→import { toast } from "sonner";
     7→import { Plug, CheckCircle2, XCircle, Loader2, ExternalLink, Mail, Brain, CreditCard } from "lucide-react";
     8→import { useState } from "react";
     9→
    10→const IntegrationsTab = () => {
    11→  const qc = useQueryClient();
    12→  const [testing, setTesting] = useState<string | null>(null);
    13→
    14→  const { data: integrations } = useQuery({
    15→    queryKey: ["admin_integrations"],
    16→    queryFn: async () => {
    17→      const { data, error } = await supabase.from("integrations").select("*").order("created_at");
    18→      if (error) throw error;
    19→      return data;
    20→    },
    21→  });
    22→
    23→  const testIntegration = async (keyName: string) => {
    24→    setTesting(keyName);
    25→    try {
    26→      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
    27→        body: { key_name: keyName },
    28→      });
    29→      if (error) throw error;
    30→      if (data.status === "success") {
    31→        toast.success("Connection successful!");
    32→      } else {
    33→        toast.error(data.error || "Connection test failed");
    34→      }
    35→      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    36→    } catch (err: any) {
    37→      toast.error(err.message);
    38→    } finally {
    39→      setTesting(null);
    40→    }
    41→  };
    42→
    43→  return (
    44→    <div className="space-y-6">
    45→      <h2 className="text-xl font-semibold">Integrations</h2>
    46→      <div className="grid gap-4">
    47→        {integrations?.map((integration: any) => {
    48→          // Skip deprecated Razorpay integration if it still exists in DB
    49→          if (integration.key_name === "RAZORPAY_KEY_ID") return null;
    50→
    51→          const iconMap: Record<string, React.ElementType> = {
    52→            OPENAI_API_KEY: Brain,
    53→            POSTMARK_API_TOKEN: Mail,
    54→            DODO_PAYMENTS_API_KEY: CreditCard,
    55→          };
    56→          const Icon = iconMap[integration.key_name] || Plug;
    57→          const dashboardLinks: Record<string, string> = {
    58→            OPENAI_API_KEY: "https://platform.openai.com/api-keys",
    59→            POSTMARK_API_TOKEN: "https://account.postmarkapp.com/servers",
    60→            DODO_PAYMENTS_API_KEY: "https://dashboard.dodopayments.com",
    61→          };
    62→          const dashboardLink = dashboardLinks[integration.key_name] ||
    63→            "https://supabase.com/dashboard/project/zkzontawprihrzpayeam/settings/functions";
    64→
    65→          return (
    66→          <Card key={integration.id}>
    67→            <CardHeader className="flex flex-row items-center justify-between pb-3">
    68→              <div className="flex items-center gap-3">
    69→                <div className="h-10 w-10 rounded-lg bg-primary/10 flex items-center justify-center">
    70→                  <Icon className="h-5 w-5 text-primary" />
    71→                </div>
    72→                <div>
    73→                  <CardTitle className="text-base">{integration.display_name}</CardTitle>
    74→                  <p className="text-sm text-muted-foreground">{integration.description}</p>
    75→                </div>
    76→              </div>
    77→              <div className="flex items-center gap-2">
    78→                {integration.last_test_status === "success" ? (
    79→                  <Badge variant="default" className="gap-1 bg-green-600"><CheckCircle2 className="h-3 w-3" />Connected</Badge>
    80→                ) : integration.last_test_status === "failed" ? (
    81→                  <Badge variant="destructive" className="gap-1"><XCircle className="h-3 w-3" />Failed</Badge>
    82→                ) : (
    83→                  <Badge variant="secondary">Not tested</Badge>
    84→                )}
    85→              </div>
    86→            </CardHeader>
    87→            <CardContent>
    88→              <div className="flex items-center justify-between">
    89→                <div className="text-sm text-muted-foreground">
    90→                  {integration.last_tested_at
    91→                    ? `Last tested: ${new Date(integration.last_tested_at).toLocaleString()}`
    92→                    : "Never tested"}
    93→                </div>
    94→                <div className="flex gap-2">
    95→                  <Button
    96→                    variant="outline"
    97→                    size="sm"
    98→                    onClick={() => testIntegration(integration.key_name)}
    99→                    disabled={testing === integration.key_name}
   100→                  >
   101→                    {testing === integration.key_name ? (
   102→                      <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" />
   103→                    ) : null}
   104→                    Test Connection
   105→                  </Button>
   106→                  <Button variant="ghost" size="sm" asChild>
   107→                    <a
   108→                      href={dashboardLink}
   109→                      target="_blank"
   110→                      rel="noopener noreferrer"
   111→                    >
   112→                      <ExternalLink className="h-3.5 w-3.5 mr-1" />
   113→                      Manage
   114→                    </a>
   115→                  </Button>
   116→                </div>
   117→              </div>
   118→            </CardContent>
   119→          </Card>
   120→          );
   121→        })}
   122→      </div>
   123→    </div>
   124→  );
   125→};
   126→
   127→export default IntegrationsTab;
   128→

