     1→import { useState } from "react";
     2→import { useQuery, useQueryClient } from "@tanstack/react-query";
     3→import { supabase } from "@/integrations/supabase/client";
     4→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
     5→import { Button } from "@/components/ui/button";
     6→import { Input } from "@/components/ui/input";
     7→import { Label } from "@/components/ui/label";
     8→import { Switch } from "@/components/ui/switch";
     9→import { Badge } from "@/components/ui/badge";
    10→import { Textarea } from "@/components/ui/textarea";
    11→import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
    12→import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
    13→import { toast } from "sonner";
    14→import { Plus, Pencil, Trash2, Flag } from "lucide-react";
    15→import { logAuditAction } from "@/lib/auditLog";
    16→
    17→interface FeatureFlag {
    18→  id: string;
    19→  key: string;
    20→  label: string;
    21→  description: string;
    22→  enabled: boolean;
    23→  value_json: Record<string, any>;
    24→  category: string;
    25→  updated_at: string;
    26→}
    27→
    28→const CATEGORIES = ["system", "features", "limits", "ai", "general"];
    29→
    30→const categoryColors: Record<string, string> = {
    31→  system: "text-destructive border-destructive/30",
    32→  features: "text-primary border-primary/30",
    33→  limits: "text-amber-600 border-amber-300",
    34→  ai: "text-purple-600 border-purple-300",
    35→  general: "text-muted-foreground",
    36→};
    37→
    38→const FeatureFlagsTab = () => {
    39→  const qc = useQueryClient();
    40→  const [editFlag, setEditFlag] = useState<FeatureFlag | null>(null);
    41→  const [isNew, setIsNew] = useState(false);
    42→  const [form, setForm] = useState({ key: "", label: "", description: "", category: "general", value_json: "{}" });
    43→  const [filterCategory, setFilterCategory] = useState("all");
    44→
    45→  const { data: flags, isLoading } = useQuery({
    46→    queryKey: ["feature_flags"],
    47→    queryFn: async () => {
    48→      const { data, error } = await supabase
    49→        .from("feature_flags")
    50→        .select("*")
    51→        .order("category")
    52→        .order("key");
    53→      if (error) throw error;
    54→      return data as FeatureFlag[];
    55→    },
    56→  });
    57→
    58→  const filtered = flags?.filter((f) => filterCategory === "all" || f.category === filterCategory) ?? [];
    59→
    60→  const grouped = filtered.reduce<Record<string, FeatureFlag[]>>((acc, f) => {
    61→    (acc[f.category] ??= []).push(f);
    62→    return acc;
    63→  }, {});
    64→
    65→  const toggleFlag = async (flag: FeatureFlag) => {
    66→    const { error } = await supabase
    67→      .from("feature_flags")
    68→      .update({ enabled: !flag.enabled } as any)
    69→      .eq("id", flag.id);
    70→    if (error) { toast.error(error.message); return; }
    71→    toast.success(`${flag.label} ${!flag.enabled ? "enabled" : "disabled"}`);
    72→    logAuditAction("feature_flag.toggle", "feature_flag", flag.id, { key: flag.key, enabled: !flag.enabled });
    73→    qc.invalidateQueries({ queryKey: ["feature_flags"] });
    74→  };
    75→
    76→  const openNew = () => {
    77→    setIsNew(true);
    78→    setForm({ key: "", label: "", description: "", category: "general", value_json: "{}" });
    79→    setEditFlag({} as FeatureFlag);
    80→  };
    81→
    82→  const openEdit = (f: FeatureFlag) => {
    83→    setIsNew(false);
    84→    setForm({
    85→      key: f.key,
    86→      label: f.label,
    87→      description: f.description,
    88→      category: f.category,
    89→      value_json: JSON.stringify(f.value_json, null, 2),
    90→    });
    91→    setEditFlag(f);
    92→  };
    93→
    94→  const save = async () => {
    95→    if (!form.key || !form.label) { toast.error("Key and label are required"); return; }
    96→    let parsedJson: any;
    97→    try {
    98→      parsedJson = JSON.parse(form.value_json);
    99→    } catch {
   100→      toast.error("Invalid JSON in value field");
   101→      return;
   102→    }
   103→
   104→    const payload = {
   105→      key: form.key,
   106→      label: form.label,
   107→      description: form.description,
   108→      category: form.category,
   109→      value_json: parsedJson,
   110→    };
   111→
   112→    if (isNew) {
   113→      const { error } = await supabase.from("feature_flags").insert(payload as any);
   114→      if (error) { toast.error(error.message); return; }
   115→      toast.success("Flag created");
   116→      logAuditAction("feature_flag.create", "feature_flag", undefined, { key: form.key, label: form.label });
   117→    } else {
   118→      const { error } = await supabase.from("feature_flags").update(payload as any).eq("id", editFlag!.id);
   119→      if (error) { toast.error(error.message); return; }
   120→      toast.success("Flag updated");
   121→      logAuditAction("feature_flag.update", "feature_flag", editFlag!.id, { key: form.key, label: form.label });
   122→    }
   123→    qc.invalidateQueries({ queryKey: ["feature_flags"] });
   124→    setEditFlag(null);
   125→  };
   126→
   127→  const deleteFlag = async (f: FeatureFlag) => {
   128→    if (!confirm(`Delete flag "${f.label}"?`)) return;
   129→    const { error } = await supabase.from("feature_flags").delete().eq("id", f.id);
   130→    if (error) { toast.error(error.message); return; }
   131→    toast.success("Flag deleted");
   132→    logAuditAction("feature_flag.delete", "feature_flag", f.id, { key: f.key, label: f.label });
   133→    qc.invalidateQueries({ queryKey: ["feature_flags"] });
   134→  };
   135→
   136→  return (
   137→    <>
   138→      <div className="space-y-6">
   139→        <div className="flex items-center justify-between">
   140→          <h2 className="text-xl font-semibold flex items-center gap-2">
   141→            <Flag className="h-5 w-5" /> Feature Flags
   142→          </h2>
   143→          <div className="flex items-center gap-2">
   144→            <Select value={filterCategory} onValueChange={setFilterCategory}>
   145→              <SelectTrigger className="w-[140px]"><SelectValue /></SelectTrigger>
   146→              <SelectContent>
   147→                <SelectItem value="all">All Categories</SelectItem>
   148→                {CATEGORIES.map((c) => <SelectItem key={c} value={c} className="capitalize">{c}</SelectItem>)}
   149→              </SelectContent>
   150→            </Select>
   151→            <Button onClick={openNew} size="sm"><Plus className="h-4 w-4 mr-1" />Add Flag</Button>
   152→          </div>
   153→        </div>
   154→
   155→        {isLoading ? (
   156→          <p className="text-muted-foreground text-sm">Loading…</p>
   157→        ) : Object.entries(grouped).length === 0 ? (
   158→          <p className="text-muted-foreground text-sm">No feature flags found.</p>
   159→        ) : (
   160→          Object.entries(grouped).map(([category, categoryFlags]) => (
   161→            <div key={category} className="space-y-3">
   162→              <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wider">{category}</h3>
   163→              <div className="grid gap-3">
   164→                {categoryFlags.map((f) => (
   165→                  <Card key={f.id}>
   166→                    <CardContent className="flex items-center justify-between p-4">
   167→                      <div className="flex-1 min-w-0 mr-4">
   168→                        <div className="flex items-center gap-2 mb-1">
   169→                          <span className="font-medium text-sm">{f.label}</span>
   170→                          <Badge variant="outline" className={`text-xs ${categoryColors[f.category] ?? ""}`}>
   171→                            {f.category}
   172→                          </Badge>
   173→                          <code className="text-xs text-muted-foreground bg-muted px-1.5 py-0.5 rounded">{f.key}</code>
   174→                        </div>
   175→                        {f.description && <p className="text-xs text-muted-foreground">{f.description}</p>}
   176→                        {Object.keys(f.value_json ?? {}).length > 0 && (
   177→                          <code className="text-xs text-muted-foreground mt-1 block">
   178→                            {JSON.stringify(f.value_json)}
   179→                          </code>
   180→                        )}
   181→                      </div>
   182→                      <div className="flex items-center gap-2 shrink-0">
   183→                        <Switch checked={f.enabled} onCheckedChange={() => toggleFlag(f)} />
   184→                        <Button variant="ghost" size="icon" onClick={() => openEdit(f)}>
   185→                          <Pencil className="h-3.5 w-3.5" />
   186→                        </Button>
   187→                        <Button variant="ghost" size="icon" onClick={() => deleteFlag(f)}>
   188→                          <Trash2 className="h-3.5 w-3.5 text-destructive" />
   189→                        </Button>
   190→                      </div>
   191→                    </CardContent>
   192→                  </Card>
   193→                ))}
   194→              </div>
   195→            </div>
   196→          ))
   197→        )}
   198→      </div>
   199→
   200→      {/* Create / Edit Dialog */}
   201→      <Dialog open={editFlag !== null} onOpenChange={(o) => !o && setEditFlag(null)}>
   202→        <DialogContent>
   203→          <DialogHeader>
   204→            <DialogTitle>{isNew ? "Create Feature Flag" : "Edit Feature Flag"}</DialogTitle>
   205→          </DialogHeader>
   206→          <div className="space-y-3">
   207→            <div>
   208→              <Label>Key (unique identifier)</Label>
   209→              <Input value={form.key} onChange={(e) => setForm({ ...form, key: e.target.value })} placeholder="e.g. dark_mode" disabled={!isNew} />
   210→            </div>
   211→            <div>
   212→              <Label>Label</Label>
   213→              <Input value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value })} placeholder="e.g. Dark Mode" />
   214→            </div>
   215→            <div>
   216→              <Label>Description</Label>
   217→              <Input value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Optional description" />
   218→            </div>
   219→            <div>
   220→              <Label>Category</Label>
   221→              <Select value={form.category} onValueChange={(v) => setForm({ ...form, category: v })}>
   222→                <SelectTrigger><SelectValue /></SelectTrigger>
   223→                <SelectContent>
   224→                  {CATEGORIES.map((c) => <SelectItem key={c} value={c} className="capitalize">{c}</SelectItem>)}
   225→                </SelectContent>
   226→              </Select>
   227→            </div>
   228→            <div>
   229→              <Label>Value (JSON)</Label>
   230→              <Textarea
   231→                value={form.value_json}
   232→                onChange={(e) => setForm({ ...form, value_json: e.target.value })}
   233→                rows={4}
   234→                className="font-mono text-xs"
   235→                placeholder='{"limit": 10}'
   236→              />
   237→            </div>
   238→            <Button onClick={save} className="w-full">{isNew ? "Create Flag" : "Save Changes"}</Button>
   239→          </div>
   240→        </DialogContent>
   241→      </Dialog>
   242→    </>
   243→  );
   244→};
   245→
   246→export default FeatureFlagsTab;
   247→

