    72→-- 3. Replace generate_job_inbox_email() with human-readable format
    73→CREATE OR REPLACE FUNCTION public.generate_job_inbox_email()
    74→  RETURNS trigger
    75→  LANGUAGE plpgsql
    76→  SECURITY DEFINER
    77→  SET search_path TO 'public'
    78→AS $function$
    79→DECLARE
    80→  user_inbox text;
    81→  domain text;
    82→  local_part text;
    83→  short_id text;
    84→BEGIN
    85→  -- Get the job owner's inbox email
    86→  SELECT inbox_email INTO user_inbox FROM public.profiles WHERE user_id = NEW.user_id;
    87→
    88→  -- Get inbound domain from config
    89→  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
    90→  IF domain IS NULL OR domain = '' THEN
    91→    domain := 'inbound.rankora.co';
    92→  END IF;
    93→
    94→  IF user_inbox IS NOT NULL AND user_inbox LIKE '%@%' THEN
    95→    local_part := split_part(user_inbox, '@', 1);
    96→  ELSE
    97→    local_part := substr(md5(NEW.user_id::text), 1, 8);
    98→  END IF;
    99→
   100→  -- Use first 8 chars of job ID as short identifier
   101→  short_id := substr(NEW.id::text, 1, 8);
   102→  NEW.inbox_email := local_part || '+j-' || short_id || '@' || domain;
   103→
   104→  RETURN NEW;
   105→END;
   106→$function$;
